import urls from './urls.js'
import api from './index.js'

// 添加投票
const addVote = function (params) {
  // return出去了一个promise
  return api.post(urls.add_vote, params)
}

// 编辑投票
const editVote = function (params) {
  // return出去了一个promise
  return api.post(urls.edit_vote, params)
}

// 删除投票
const delVote = function (params) {
  // return出去了一个promise
  return api.post(urls.del_vote, params)
}

// 图片上传 支持单张 多张
const ajaxUploadPic = function (params) {
  // return出去了一个promise
  return api.post(urls.ajax_upload_pic, params)
}

// 投票列表
const voteList = function (params) {
  return api.post(urls.vote_list, params)
}

// 投票详情
const voteDetail = function (params) {
  return api.post(urls.vote_detail, params)
}

// 单个投票数据统计详情
const statisticalVoteDetail = function (params) {
  return api.post(urls.statistical_vote_detail, params)
}

// 投票区块投票详情
const statisticalVoteBlockDetail = function (params) {
  return api.post(urls.statistical_vote_block_detail, params)
}

// 投票导出
const exportVote = function (params) {
  return api.post(urls.export, params)
}

// 投票导出下载
const downloadExportFile = function (params) {
  return api.post(urls.download_export_file, params)
}

export default {
  addVote,
  editVote,
  delVote,
  ajaxUploadPic,
  voteList,
  voteDetail,
  statisticalVoteDetail,
  statisticalVoteBlockDetail,
  exportVote,
  downloadExportFile
}
